14|    return session_handle_invalid_connection(session, frame, NGHTTP2_ERR_PROTO,
15|                                             "PRIORITY_UPDATE: stream_id == 0");
16|  }
17|
18|  if (nghttp2_session_is_my_stream_id(session, priority_update->stream_id)) {
19|    if (session_detect_idle_stream(session, priority_update->stream_id)) {
20|      return session_handle_invalid_connection(
21|          session, frame, NGHTTP2_ERR_PROTO,
22|          "PRIORITY_UPDATE: prioritizing idle push is not allowed");
23|    }
24|
25|    /* TODO Ignore priority signal to a push stream for now */
26|    return session_call_on_frame_received(session, frame);
27|  }
28|
29|  stream = nghttp2_session_get_stream_raw(session, priority_update->stream_id);
30|  if (stream) {
31|    /* Stream already exists. */
32|  } else if (session_detect_idle_stream(session, priority_update->stream_id)) {
33|    if (session->num_idle_streams + session->num_incoming_streams >=
34|        session->local_settings.max_concurrent_streams) {
35|      return session_handle_invalid_connection(
36|          session, frame, NGHTTP2_ERR_PROTO,
37|          "PRIORITY_UPDATE: max concurrent streams exceeded");
38|    }
39|
40|    nghttp2_priority_spec_default_init(&pri_spec);
41|    stream = nghttp2_session_open_stream(session, priority_update->stream_id,
42|                                         NGHTTP2_FLAG_NONE, &pri_spec,
43|                                         NGHTTP2_STREAM_IDLE, NULL);
44|    if (!stream) {
45|      return NGHTTP2_ERR_NOMEM;
46|    }
47|  } else {
48|    return session_call_on_frame_received(session, frame);
49|  }
50|
51|  extpri.urgency = NGHTTP2_EXTPRI_DEFAULT_URGENCY;
52|  extpri.inc = 0;
53|
54|  rv = nghttp2_http_parse_priority(&extpri, priority_update->field_value,
55|                                   priority_update->field_value_len);
56|  if (rv != 0) {
57|    /* Just ignore field_value if it cannot be parsed. */
58|    return session_call_on_frame_received(session, frame);
59|  }
