5309|
5310|    /* TODO Ignore priority signal to a push stream for now */
5311|    return session_call_on_frame_received(session, frame);
5312|  }
5313|
5314|  stream = nghttp2_session_get_stream_raw(session, priority_update->stream_id);
5315|  if (stream) {
5316|    /* Stream already exists. */
5317|  } else if (session_detect_idle_stream(session, priority_update->stream_id)) {
5318|    if (session->num_idle_streams + session->num_incoming_streams >=
5319|        session->local_settings.max_concurrent_streams) {
5320|      return session_handle_invalid_connection(
5321|          session, frame, NGHTTP2_ERR_PROTO,
5322|          "PRIORITY_UPDATE: max concurrent streams exceeded");
5323|    }
5324|
5325|    nghttp2_priority_spec_default_init(&pri_spec);
5326|    stream = nghttp2_session_open_stream(session, priority_update->stream_id,
5327|                                         NGHTTP2_FLAG_NONE, &pri_spec,
5328|                                         NGHTTP2_STREAM_IDLE, NULL);
5329|    if (!stream) {
5330|      return NGHTTP2_ERR_NOMEM;
5331|    }
5332|  } else {
5333|    return session_call_on_frame_received(session, frame);
5334|  }
